class Solution {
    public boolean primeSubOperation(int[] nums){
        int maximum=Arrays.stream(nums).max().getAsInt();
        boolean[] composite=new boolean[maximum+1];
        List<Integer> primes=new ArrayList<>();
        for(int number=2;number<=maximum;number++){
            if(!composite[number]){
                primes.add(number);
                if((long)number*number<=maximum)for(int multiple=number*number;multiple<=maximum;multiple+=number)composite[multiple]=true;
            }
        }
        int previous=0;
        for(int value:nums){
            if(value<=previous)return false;
            int limit=value-previous,index=Collections.binarySearch(primes,limit);
            index=index>=0?index-1:-index-2;
            if(index>=0)value-=primes.get(index);
            previous=value;
        }
        return true;
    }
}

