class Solution {
    public:bool primeSubOperation(vector<int>& nums){
        int maximum=*max_element(nums.begin(),nums.end());
        vector<bool> composite(maximum+1);
        vector<int> primes;
        for(int number=2;number<=maximum;++number)if(!composite[number]){
            primes.push_back(number);
            if(1LL*number*number<=maximum)for(int multiple=number*number;multiple<=maximum;multiple+=number)composite[multiple]=true;
        }
        int previous=0;
        for(int value:nums){
            if(value<=previous)return false;
            int limit=value-previous;
            auto iterator=lower_bound(primes.begin(),primes.end(),limit);
            if(iterator!=primes.begin())value-=*prev(iterator);
            previous=value;
        }
        return true;
    }
};
